cat > terminal_size/src/lib.rs <<'EOF'
//! Minimal terminal size query (shim with the same API surface as the
//! `terminal_size` crate, implemented locally with an ioctl).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Width(pub u16);
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Height(pub u16);

pub fn terminal_size() -> Option<(Width, Height)> {
    terminal_size_of_fd(libc::STDOUT_FILENO)
}

pub fn terminal_size_of_fd(fd: libc::c_int) -> Option<(Width, Height)> {
    unsafe {
        if libc::isatty(fd) != 1 {
            return None;
        }
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) == -1 {
            return None;
        }
        if ws.ws_col == 0 || ws.ws_row == 0 {
            return None;
        }
        Some((Width(ws.ws_col), Height(ws.ws_row)))
    }
}
EOF
