{"command":"cd /workspace && cat > src/toml.rs <<'EOF'
//! A small TOML reader.
//!
//! It parses a document into an ordered tree of key/value entries.  Entries
//! are kept in document order and duplicate keys are *not* rejected by the
//! parser itself (the consumer decides what to do with them), while a table
//! header that is defined twice is rejected.

#[derive(Debug, Clone)]
pub enum Value {
    Str(String),
    Int(i64),
    Float(f64),
    Bool(bool),
    Datetime(String),
    Array(Vec<Value>),
    /// `{ a = 1 }`
    InlineTable(Vec<(String, Value)>),
    /// Table created by dotted keys, e.g. `a.b = 1`.
    DottedTable(Vec<(String, Value)>),
    /// Table created by a `[header]` (or implicitly by a deeper header).
    Table(Table),
    /// Array of tables created by `[[header]]`.
    ArrayOfTables(Vec<Table>),
}

#[derive(Debug, Clone, Default)]
pub struct Table {
    pub explicit: bool,
    pub entries: Vec<(String, Value)>,
}

impl Value {
    /// Entries of any table-like value.
    pub fn entries(&self) -> Option<&[(String, Value)]> {
        match self {
            Value::InlineTable(e) | Value::DottedTable(e) => Some(e),
            Value::Table(t) => Some(&t.entries),
            _ => None,
        }
    }
}

#[derive(Debug)]
pub struct ParseError;

type Result<T> = std::result::Result<T, ParseError>;

pub fn parse(input: &str) -> Result<Table> {
    let input = input.strip_prefix('\u{feff}').unwrap_or(input);
    let mut p = Parser {
        s: input.as_bytes(),
        src: input,
        pos: 0,
    };
    let mut root = Table {
        explicit: true,
        entries: Vec::new(),
    };
    // Path of the table currently receiving key/value pairs.
    let mut cur: Vec<String> = Vec::new();
    loop {
        p.skip_ws_and_newlines_and_comments();
        if p.at_end() {
            break;
        }
        if p.peek() == Some(b'[') {
            p.pos += 1;
            let array = if p.peek() == Some(b'[') {
                p.pos += 1;
                true
            } else {
                false
            };
            p.skip_ws();
            let path = p.dotted_key()?;
            p.skip_ws();
            p.expect(b']')?;
            if array {
                p.expect(b']')?;
            }
            p.end_of_line()?;
            define_table(&mut root, &path, array)?;
            cur = path;
        } else {
            let key = p.dotted_key()?;
            p.skip_ws();
            p.expect(b'=')?;
            p.skip_ws();
            let value = p.value()?;
            p.end_of_line()?;
            let table = current_table(&mut root, &cur);
            add_dotted_key(&mut table.entries, &key, value)?;
        }
    }
    Ok(root)
}

/// Locates the table (created by headers) at `path`.
fn current_table<'a>(root: &'a mut Table, path: &[String]) -> &'a mut Table {
    let mut t = root;
    for part in path {
        let idx = t
            .entries
            .iter()
            .rposition(|(k, v)| k == part && matches!(v, Value::Table(_) | Value::ArrayOfTables(_)))
            .expect("table path was defined");
        t = match &mut t.entries[idx].1 {
            Value::Table(t) => t,
            Value::ArrayOfTables(v) => v.last_mut().expect("non-empty array of tables"),
            _ => unreachable!(),
        };
    }
    t
}

fn define_table(root: &mut Table, path: &[String], array: bool) -> Result<()> {
    let (last, parents) = path.split_last().ok_or(ParseError)?;
    let mut t = root;
    for part in parents {
        let idx = t
            .entries
            .iter()
            .rposition(|(k, v)| k == part && matches!(v, Value::Table(_) | Value::ArrayOfTables(_)));
        let idx = match idx {
            Some(i) => i,
            None => {
                t.entries.push((part.clone(), Value::Table(Table::default())));
                t.entries.len() - 1
            }
        };
        t = match &mut t.entries[idx].1 {
            Value::Table(t) => t,
            Value::ArrayOfTables(v) => v.last_mut().ok_or(ParseError)?,
            _ => unreachable!(),
        };
    }
    let existing = t
        .entries
        .iter()
        .rposition(|(k, v)| k == last && matches!(v, Value::Table(_) | Value::ArrayOfTables(_)));
    match (existing, array) {
        (Some(i), true) => match &mut t.entries[i].1 {
            Value::ArrayOfTables(v) => {
                v.push(Table {
                    explicit: true,
                    entries: Vec::new(),
                });
                Ok(())
            }
            _ => Err(ParseError),
        },
        (Some(i), false) => match &mut t.entries[i].1 {
            Value::Table(existing) if !existing.explicit => {
                existing.explicit = true;
                Ok(())
            }
            _ => Err(ParseError),
        },
        (None, true) => {
            t.entries.push((
                last.clone(),
                Value::ArrayOfTables(vec![Table {
                    explicit: true,
                    entries: Vec::new(),
                }]),
            ));
            Ok(())
        }
        (None, false) => {
            t.entries.push((
                last.clone(),
                Value::Table(Table {
                    explicit: true,
                    entries: Vec::new(),
                }),
            ));
            Ok(())
        }
    }
}

fn add_dotted_key(entries: &mut Vec<(String, Value)>, key: &[String], value: Value) -> Result<()> {
    let (first, rest) = key.split_first().ok_or(ParseError)?;
    if rest.is_empty() {
        entries.push((first.clone(), value));
        return Ok(());
    }
    let idx = match entries.iter().rposition(|(k, _)| k == first) {
        Some(i) => match &entries[i].1 {
            Value::DottedTable(_) => i,
            _ => return Err(ParseError),
        },
        None => {
            entries.push((first.clone(), Value::DottedTable(Vec::new())));
            entries.len() - 1
        }
    };
    match &mut entries[idx].1 {
        Value::DottedTable(inner) => add_dotted_key(inner, rest, value),
        _ => unreachable!(),
    }
}

struct Parser<'a> {
    s: &'a [u8],
    src: &'a str,
    pos: usize,
}

fn is_bare_key_char(c: u8) -> bool {
    c.is_ascii_alphanumeric() || c == b'_' || c == b'-'
}

impl<'a> Parser<'a> {
    fn at_end(&self) -> bool {
        self.pos >= self.s.len()
    }

    fn peek(&self) -> Option<u8> {
        self.s.get(self.pos).copied()
    }

    fn peek_at(&self, off: usize) -> Option<u8> {
        self.s.get(self.pos + off).copied()
    }

    fn expect(&mut self, c: u8) -> Result<()> {
        if self.peek() == Some(c) {
            self.pos += 1;
            Ok(())
        } else {
            Err(ParseError)
        }
    }

    fn skip_ws(&mut self) {
        while matches!(self.peek(), Some(b' ') | Some(b'\t')) {
            self.pos += 1;
        }
    }

    fn skip_comment(&mut self) {
        if self.peek() == Some(b'#') {
            while let Some(c) = self.peek() {
                if c == b'\n' {
                    break;
                }
                if c == b'\r' && self.peek_at(1) == Some(b'\n') {
                    break;
                }
                self.pos += 1;
            }
        }
    }

    /// Consumes a newline; returns false if there is none.
    fn newline(&mut self) -> bool {
        match self.peek() {
            Some(b'\n') => {
                self.pos += 1;
                true
            }
            Some(b'\r') if self.peek_at(1) == Some(b'\n') => {
                self.pos += 2;
                true
            }
            _ => false,
        }
    }

    fn skip_ws_and_newlines_and_comments(&mut self) {
        loop {
            self.skip_ws();
            self.skip_comment();
            if !self.newline() {
                break;
            }
        }
    }

    /// Whitespace, optional comment, then newline or end of input.
    fn end_of_line(&mut self) -> Result<()> {
        self.skip_ws();
        self.skip_comment();
        if self.at_end() || self.newline() {
            Ok(())
        } else {
            Err(ParseError)
        }
    }

    fn dotted_key(&mut self) -> Result<Vec<String>> {
        let mut parts = vec![self.simple_key()?];
        loop {
            let save = self.pos;
            self.skip_ws();
            if self.peek() == Some(b'.') {
                self.pos += 1;
                self.skip_ws();
                parts.push(self.simple_key()?);
            } else {
                self.pos = save;
                break;
            }
        }
        Ok(parts)
    }

    fn simple_key(&mut self) -> Result<String> {
        match self.peek() {
            Some(b'"') => {
                if self.src[self.pos..].starts_with("\"\"\"") {
                    return Err(ParseError);
                }
                self.pos += 1;
                self.basic_string_body()
            }
            Some(b'\'') => {
                if self.src[self.pos..].starts_with("'''") {
                    return Err(ParseError);
                }
                self.pos += 1;
                self.literal_string_body()
            }
            Some(c) if is_bare_key_char(c) => {
                let start = self.pos;
                while matches!(self.peek(), Some(c) if is_bare_key_char(c)) {
                    self.pos += 1;
                }
                Ok(self.src[start..self.pos].to_owned())
            }
            _ => Err(ParseError),
        }
    }

    /// Body of a single-line basic string; the opening quote is consumed.
    fn basic_string_body(&mut self) -> Result<String> {
        let mut out = String::new();
        loop {
            let c = self.next_char().ok_or(ParseError)?;
            match c {
                '"' => return Ok(out),
                '\\' => out.push_str(&self.escape()?),
                '\n' | '\r' => return Err(ParseError),
                c if (c as u32) < 0x20 && c != '\t' => return Err(ParseError),
                '\u{7f}' => return Err(ParseError),
                c => out.push(c),
            }
        }
    }

    fn literal_string_body(&mut self) -> Result<String> {
        let mut out = String::new();
        loop {
            let c = self.next_char().ok_or(ParseError)?;
            match c {
                '\'' => return Ok(out),
                '\n' | '\r' => return Err(ParseError),
                c if (c as u32) < 0x20 && c != '\t' => return Err(ParseError),
                '\u{7f}' => return Err(ParseError),
                c => out.push(c),
            }
        }
    }

    fn next_char(&mut self) -> Option<char> {
        let c = self.src[self.pos..].chars().next()?;
        self.pos += c.len_utf8();
        Some(c)
    }

    /// Parses an escape sequence; the backslash is consumed.
    fn escape(&mut self) -> Result<String> {
        let c = self.next_char().ok_or(ParseError)?;
        Ok(match c {
            'b' => "\u{8}".to_owned(),
            't' => "\t".to_owned(),
            'n' => "\n".to_owned(),
            'f' => "\u{c}".to_owned(),
            'r' => "\r".to_owned(),
            '"' => "\"".to_owned(),
            '\\' => "\\".to_owned(),
            'u' => self.unicode_escape(4)?,
            'U' => self.unicode_escape(8)?,
            _ => return Err(ParseError),
        })
    }

    fn unicode_escape(&mut self, len: usize) -> Result<String> {
        if self.pos + len > self.s.len() {
            return Err(ParseError);
        }
        let hex = &self.src[self.pos..self.pos + len];
        if !hex.bytes().all(|b| b.is_ascii_hexdigit()) {
            return Err(ParseError);
        }
        self.pos += len;
        let n = u32::from_str_radix(hex, 16).map_err(|_| ParseError)?;
        char::from_u32(n).map(|c| c.to_string()).ok_or(ParseError)
    }

    fn multiline_basic_string(&mut self) -> Result<String> {
        // opening """ already consumed
        self.newline();
        let mut out = String::new();
        loop {
            if self.src[self.pos..].starts_with("\"\"\"") {
                self.pos += 3;
                // up to two additional quotes belong to the content
                while self.peek() == Some(b'"') && out.len() < usize::MAX {
                    out.push('"');
                    self.pos += 1;
                }
                return Ok(out);
            }
            let c = self.next_char().ok_or(ParseError)?;
            match c {
                '\\' => {
                    // line ending backslash
                    let save = self.pos;
                    self.skip_ws();
                    if self.newline() {
                        self.skip_ws_and_newlines_and_comments_no_comment();
                    } else {
                        self.pos = save;
                        out.push_str(&self.escape()?);
                    }
                }
                '\r' => {
                    if self.peek() == Some(b'\n') {
                        self.pos += 1;
                        out.push('\n');
                    } else {
                        return Err(ParseError);
                    }
                }
                c if (c as u32) < 0x20 && c != '\t' && c != '\n' => return Err(ParseError),
                '\u{7f}' => return Err(ParseError),
                c => out.push(c),
            }
        }
    }

    fn skip_ws_and_newlines_and_comments_no_comment(&mut self) {
        loop {
            self.skip_ws();
            if !self.newline() {
                break;
            }
        }
    }

    fn multiline_literal_string(&mut self) -> Result<String> {
        self.newline();
        let mut out = String::new();
        loop {
            if self.src[self.pos..].starts_with("'''") {
                self.pos += 3;
                while self.peek() == Some(b'\'') {
                    out.push('\'');
                    self.pos += 1;
                }
                return Ok(out);
            }
            let c = self.next_char().ok_or(ParseError)?;
            match c {
                '\r' => {
                    if self.peek() == Some(b'\n') {
                        self.pos += 1;
                        out.push('\n');
                    } else {
                        return Err(ParseError);
                    }
                }
                c if (c as u32) < 0x20 && c != '\t' && c != '\n' => return Err(ParseError),
                '\u{7f}' => return Err(ParseError),
                c => out.push(c),
            }
        }
    }

    fn value(&mut self) -> Result<Value> {
        match self.peek() {
            Some(b'"') => {
                if self.src[self.pos..].starts_with("\"\"\"") {
                    self.pos += 3;
                    Ok(Value::Str(self.multiline_basic_string()?))
                } else {
                    self.pos += 1;
                    Ok(Value::Str(self.basic_string_body()?))
                }
            }
            Some(b'\'') => {
                if self.src[self.pos..].starts_with("'''") {
                    self.pos += 3;
                    Ok(Value::Str(self.multiline_literal_string()?))
                } else {
                    self.pos += 1;
                    Ok(Value::Str(self.literal_string_body()?))
                }
            }
            Some(b'[') => self.array(),
            Some(b'{') => self.inline_table(),
            Some(b't') | Some(b'f') => {
                let word = self.word();
                match word {
                    "true" => Ok(Value::Bool(true)),
                    "false" => Ok(Value::Bool(false)),
                    _ => Err(ParseError),
                }
            }
            Some(c) if c.is_ascii_digit() || c == b'+' || c == b'-' || c == b'i' || c == b'n' => {
                self.number_or_datetime()
            }
            _ => Err(ParseError),
        }
    }

    /// Reads a run of bare-key-like characters.
    fn word(&mut self) -> &'a str {
        let start = self.pos;
        while matches!(self.peek(), Some(c) if is_bare_key_char(c)) {
            self.pos += 1;
        }
        &self.src[start..self.pos]
    }

    fn array(&mut self) -> Result<Value> {
        self.expect(b'[')?;
        let mut items = Vec::new();
        loop {
            self.skip_ws_and_newlines_and_comments();
            if self.peek() == Some(b']') {
                self.pos += 1;
                return Ok(Value::Array(items));
            }
            items.push(self.value()?);
            self.skip_ws_and_newlines_and_comments();
            match self.peek() {
                Some(b',') => {
                    self.pos += 1;
                }
                Some(b']') => {
                    self.pos += 1;
                    return Ok(Value::Array(items));
                }
                _ => return Err(ParseError),
            }
        }
    }

    fn inline_table(&mut self) -> Result<Value> {
        self.expect(b'{')?;
        let mut entries = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') {
            self.pos += 1;
            return Ok(Value::InlineTable(entries));
        }
        loop {
            self.skip_ws();
            let key = self.dotted_key()?;
            self.skip_ws();
            self.expect(b'=')?;
            self.skip_ws();
            let value = self.value()?;
            add_dotted_key(&mut entries, &key, value)?;
            self.skip_ws();
            match self.peek() {
                Some(b',') => {
                    self.pos += 1;
                }
                Some(b'}') => {
                    self.pos += 1;
                    return Ok(Value::InlineTable(entries));
                }
                _ => return Err(ParseError),
            }
        }
    }

    fn digits_at(&self, off: usize, n: usize) -> bool {
        (0..n).all(|i| matches!(self.peek_at(off + i), Some(c) if c.is_ascii_digit()))
    }

    fn number_or_datetime(&mut self) -> Result<Value> {
        // Date: YYYY-MM-DD
        if self.digits_at(0, 4) && self.peek_at(4) == Some(b'-') && self.digits_at(5, 2) && self.peek_at(7) == Some(b'-') && self.digits_at(8, 2) {
            let start = self.pos;
            self.pos += 10;
            // optional time
            let has_time = match self.peek() {
                Some(b'T') | Some(b't') => {
                    self.pos += 1;
                    true
                }
                Some(b' ') if self.digits_at(1, 2) && self.peek_at(3) == Some(b':') => {
                    self.pos += 1;
                    true
                }
                _ => false,
            };
            if has_time {
                self.time_part()?;
                match self.peek() {
                    Some(b'Z') | Some(b'z') => self.pos += 1,
                    Some(b'+') | Some(b'-') => {
                        self.pos += 1;
                        if !(self.digits_at(0, 2) && self.peek_at(2) == Some(b':') && self.digits_at(3, 2)) {
                            return Err(ParseError);
                        }
                        self.pos += 5;
                    }
                    _ => {}
                }
            }
            self.check_delimiter()?;
            return Ok(Value::Datetime(self.src[start..self.pos].to_owned()));
        }
        // Local time: HH:MM:SS
        if self.digits_at(0, 2) && self.peek_at(2) == Some(b':') {
            let start = self.pos;
            self.time_part()?;
            self.check_delimiter()?;
            return Ok(Value::Datetime(self.src[start..self.pos].to_owned()));
        }
        self.number()
    }

    fn time_part(&mut self) -> Result<()> {
        if !(self.digits_at(0, 2) && self.peek_at(2) == Some(b':') && self.digits_at(3, 2) && self.peek_at(5) == Some(b':') && self.digits_at(6, 2)) {
            return Err(ParseError);
        }
        self.pos += 8;
        if self.peek() == Some(b'.') {
            self.pos += 1;
            if !self.digits_at(0, 1) {
                return Err(ParseError);
            }
            while matches!(self.peek(), Some(c) if c.is_ascii_digit()) {
                self.pos += 1;
            }
        }
        Ok(())
    }

    /// A value must be followed by a delimiter.
    fn check_delimiter(&self) -> Result<()> {
        match self.peek() {
            None | Some(b' ') | Some(b'\t') | Some(b'\n') | Some(b'\r') | Some(b',') | Some(b']') | Some(b'}') | Some(b'#') => Ok(()),
            _ => Err(ParseError),
        }
    }

    fn number(&mut self) -> Result<Value> {
        let start = self.pos;
        let mut negative = false;
        match self.peek() {
            Some(b'+') => self.pos += 1,
            Some(b'-') => {
                negative = true;
                self.pos += 1;
            }
            _ => {}
        }
        let rest = &self.src[self.pos..];
        if rest.starts_with("inf") {
            self.pos += 3;
            self.check_delimiter()?;
            return Ok(Value::Float(if negative { f64::NEG_INFINITY } else { f64::INFINITY }));
        }
        if rest.starts_with("nan") {
            self.pos += 3;
            self.check_delimiter()?;
            return Ok(Value::Float(f64::NAN));
        }
        if self.peek() == Some(b'0') {
            let radix = match self.peek_at(1) {
                Some(b'x') => Some(16),
                Some(b'o') => Some(8),
                Some(b'b') => Some(2),
                _ => None,
            };
            if let Some(radix) = radix {
                if start != self.pos {
                    // sign not allowed with prefixed integers
                    return Err(ParseError);
                }
                self.pos += 2;
                let digits = self.digit_run(|c| (c as char).is_digit(radix))?;
                self.check_delimiter()?;
                let n = i64::from_str_radix(&digits, radix).map_err(|_| ParseError)?;
                return Ok(Value::Int(n));
            }
        }
        let int_part = self.digit_run(|c| c.is_ascii_digit())?;
        if int_part.len() > 1 && int_part.starts_with('0') {
            return Err(ParseError);
        }
        let mut is_float = false;
        let mut text = String::new();
        if negative {
            text.push('-');
        }
        text.push_str(&int_part);
        if self.peek() == Some(b'.') && matches!(self.peek_at(1), Some(c) if c.is_ascii_digit()) {
            self.pos += 1;
            is_float = true;
            text.push('.');
            text.push_str(&self.digit_run(|c| c.is_ascii_digit())?);
        } else if self.peek() == Some(b'.') {
            return Err(ParseError);
        }
        if matches!(self.peek(), Some(b'e') | Some(b'E')) {
            self.pos += 1;
            is_float = true;
            text.push('e');
            if matches!(self.peek(), Some(b'+') | Some(b'-')) {
                text.push(self.peek().unwrap() as char);
                self.pos += 1;
            }
            text.push_str(&self.digit_run(|c| c.is_ascii_digit())?);
        }
        self.check_delimiter()?;
        if is_float {
            text.parse::<f64>().map(Value::Float).map_err(|_| ParseError)
        } else {
            text.parse::<i64>().map(Value::Int).map_err(|_| ParseError)
        }
    }

    /// Reads digits separated by single underscores; returns them without
    /// the underscores.
    fn digit_run(&mut self, is_digit: impl Fn(u8) -> bool) -> Result<String> {
        let mut out = String::new();
        let mut last_underscore = true; // disallow leading underscore
        loop {
            match self.peek() {
                Some(c) if is_digit(c) => {
                    out.push(c as char);
                    last_underscore = false;
                    self.pos += 1;
                }
                Some(b'_') => {
                    if last_underscore {
                        return Err(ParseError);
                    }
                    last_underscore = true;
                    self.pos += 1;
                }
                _ => break,
            }
        }
        if out.is_empty() || last_underscore {
            return Err(ParseError);
        }
        Ok(out)
    }
}
