//! Error type reported to the user.

use std::fmt;

#[derive(Debug)]
pub enum Error {
    /// Any I/O failure (configuration file, git invocation, output file...).
    Io,
    /// The configuration file could not be parsed.
    Config,
    /// A version string could not be parsed as semantic version.
    SemVer,
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::Io => write!(f, "fatal I/O error with output file"),
            Error::Config => write!(f, "Failed to parse TOML configuration file"),
            Error::SemVer => write!(
                f,
                "Failed to parse version into valid SemVer. Ensure the version is in the X.Y.Z format."
            ),
        }
    }
}

impl From<std::io::Error> for Error {
    fn from(_: std::io::Error) -> Self {
        Error::Io
    }
}

impl From<crate::toml::ParseError> for Error {
    fn from(_: crate::toml::ParseError) -> Self {
        Error::Config
    }
}
