//! The `.clog.toml` configuration file.

use crate::error::Error;
use crate::toml::{self, Value};
use crate::{Format, LinkStyle};

#[derive(Debug, Default)]
pub struct Config {
    pub repository: Option<String>,
    pub subtitle: Option<String>,
    pub link_style: Option<LinkStyle>,
    pub output_format: Option<Format>,
    pub from_latest_tag: Option<bool>,
    pub changelog: Option<String>,
    pub outfile: Option<String>,
    pub infile: Option<String>,
    pub git_dir: Option<String>,
    pub git_work_tree: Option<String>,
    /// `[sections]`: section title -> aliases, in document order.
    pub sections: Option<Vec<(String, Vec<String>)>>,
}

pub fn parse(text: &str) -> Result<Config, Error> {
    let root = toml::parse(text)?;
    let mut clog: Option<Config> = None;
    let mut sections: Option<Vec<(String, Vec<String>)>> = None;
    for (key, value) in &root.entries {
        match key.as_str() {
            "clog" => {
                if clog.is_some() {
                    return Err(Error::Config);
                }
                let entries = value.entries().ok_or(Error::Config)?;
                clog = Some(parse_clog(entries)?);
            }
            "sections" => {
                if sections.is_some() {
                    return Err(Error::Config);
                }
                let entries = value.entries().ok_or(Error::Config)?;
                sections = Some(parse_sections(entries)?);
            }
            _ => {}
        }
    }
    let mut cfg = clog.ok_or(Error::Config)?;
    cfg.sections = sections;
    Ok(cfg)
}

fn set_string(slot: &mut Option<String>, value: &Value) -> Result<(), Error> {
    if slot.is_some() {
        return Err(Error::Config);
    }
    match value {
        Value::Str(s) => {
            *slot = Some(s.clone());
            Ok(())
        }
        _ => Err(Error::Config),
    }
}

fn parse_clog(entries: &[(String, Value)]) -> Result<Config, Error> {
    let mut cfg = Config::default();
    for (key, value) in entries {
        match key.as_str() {
            "repository" => set_string(&mut cfg.repository, value)?,
            "subtitle" => set_string(&mut cfg.subtitle, value)?,
            "changelog" => set_string(&mut cfg.changelog, value)?,
            "outfile" => set_string(&mut cfg.outfile, value)?,
            "infile" => set_string(&mut cfg.infile, value)?,
            "git-dir" => set_string(&mut cfg.git_dir, value)?,
            "git-work-tree" => set_string(&mut cfg.git_work_tree, value)?,
            "link-style" => {
                let mut s = None;
                set_string(&mut s, value)?;
                if cfg.link_style.is_some() {
                    return Err(Error::Config);
                }
                cfg.link_style = Some(LinkStyle::parse(&s.unwrap()).ok_or(Error::Config)?);
            }
            "output-format" => {
                let mut s = None;
                set_string(&mut s, value)?;
                if cfg.output_format.is_some() {
                    return Err(Error::Config);
                }
                cfg.output_format = Some(Format::parse(&s.unwrap()).ok_or(Error::Config)?);
            }
            "from-latest-tag" => {
                if cfg.from_latest_tag.is_some() {
                    return Err(Error::Config);
                }
                match value {
                    Value::Bool(b) => cfg.from_latest_tag = Some(*b),
                    _ => return Err(Error::Config),
                }
            }
            _ => {}
        }
    }
    Ok(cfg)
}

fn parse_sections(entries: &[(String, Value)]) -> Result<Vec<(String, Vec<String>)>, Error> {
    let mut out: Vec<(String, Vec<String>)> = Vec::new();
    for (key, value) in entries {
        let aliases = match value {
            Value::Array(items) => items
                .iter()
                .map(|v| match v {
                    Value::Str(s) => Ok(s.clone()),
                    _ => Err(Error::Config),
                })
                .collect::<Result<Vec<_>, _>>()?,
            _ => return Err(Error::Config),
        };
        // Later definitions replace earlier ones but keep the original position.
        if let Some(existing) = out.iter_mut().find(|(k, _)| k == key) {
            existing.1 = aliases;
        } else {
            out.push((key.clone(), aliases));
        }
    }
    Ok(out)
}
