//! Version bumping based on the latest git tag.

use crate::error::Error;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Bump {
    Major,
    Minor,
    Patch,
}

/// Increments `raw` (the output of `git describe`) according to `bump`.
///
/// A leading run of `v`/`V` characters is accepted and reproduced as a single
/// `v` prefix.  Pre-release and build metadata are preserved.
pub fn bump(raw: &str, bump: Bump) -> Result<String, Error> {
    let stripped = raw.trim_start_matches(['v', 'V']);
    let had_prefix = stripped.len() != raw.len();
    let mut ver = semver::Version::parse(stripped).map_err(|_| Error::SemVer)?;
    match bump {
        Bump::Major => {
            ver.major += 1;
            ver.minor = 0;
            ver.patch = 0;
        }
        Bump::Minor => {
            ver.minor += 1;
            ver.patch = 0;
        }
        Bump::Patch => {
            ver.patch += 1;
        }
    }
    Ok(if had_prefix {
        format!("v{ver}")
    } else {
        ver.to_string()
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bumps() {
        assert_eq!(bump("1.2.3", Bump::Major).unwrap(), "2.0.0");
        assert_eq!(bump("1.2.3", Bump::Minor).unwrap(), "1.3.0");
        assert_eq!(bump("1.2.3", Bump::Patch).unwrap(), "1.2.4");
        assert_eq!(bump("vV1.2.3-rc.1+b", Bump::Patch).unwrap(), "v1.2.4-rc.1+b");
        assert!(bump("1.2.3\n", Bump::Patch).is_err());
        assert!(bump("01.2.3", Bump::Patch).is_err());
        assert!(bump("", Bump::Patch).is_err());
    }
}
