//! Parsing of raw `git log` output into commits grouped by section.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use regex::Regex;

use crate::panic;

/// A single conventional commit.
#[derive(Debug, Clone)]
pub struct Commit {
    pub hash: String,
    pub subject: String,
    pub component: String,
    /// Issue numbers closed by this commit (`Closes #12`).
    pub closes: Vec<String>,
    /// Issue numbers of breaking changes (`Breaks #12`), or an empty string
    /// for a `BREAKING CHANGE` note without an issue.
    pub breaks: Vec<String>,
}

/// Section title -> aliases (commit types).
pub type Sections = Vec<(String, Vec<String>)>;

/// Commits grouped by section (in configuration order) and component
/// (sorted).
pub struct SectionMap {
    pub sections: Vec<(String, BTreeMap<String, Vec<Commit>>)>,
}

fn subject_re() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"^([^(:]+)(?:\(([^)]*)\))?:(.*)").expect("valid regex"))
}

fn closes_re() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"(?:Closes|Fixes|Resolves)\s((?:#(\d+)(?:,\s)?)+)").expect("valid regex"))
}

fn breaks_re() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"Breaks\s((?:#(\d+)(?:,\s)?)+)").expect("valid regex"))
}

fn breaking_re() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"(?i)breaking").expect("valid regex"))
}

/// Returns the title of the first section having `alias` among its aliases.
fn section_for<'a>(sections: &'a Sections, alias: &str) -> Option<&'a str> {
    sections
        .iter()
        .find(|(_, aliases)| aliases.iter().any(|a| a == alias))
        .map(|(title, _)| title.as_str())
}

/// Parses one `%H%n%s%n%b` block.  Returns the commit together with the
/// title of the section it belongs to, or `None` when it does not belong to
/// any configured section.
fn parse_raw_commit<'a>(sections: &'a Sections, raw: &str) -> Option<(&'a str, Commit)> {
    let mut lines = raw.split('\n');
    let hash = lines.next().unwrap_or("").to_owned();
    let (section, subject, component) = match lines.next().and_then(|s| subject_re().captures(s)) {
        Some(caps) => {
            let alias = caps.get(1).map(|m| m.as_str()).unwrap_or("");
            let section = section_for(sections, alias)?;
            let component = caps.get(2).map(|m| m.as_str()).unwrap_or("").to_owned();
            let subject = caps.get(3).map(|m| m.as_str()).unwrap_or("").to_owned();
            (section, subject, component)
        }
        None => {
            // Commits without a conventional subject fall back to the
            // "unknown" section, which cannot be resolved any further.
            if section_for(sections, "unk").is_some() {
                panic::unwrap_none(panic::UNKNOWN_SECTION);
            }
            return None;
        }
    };

    let mut closes = Vec::new();
    let mut breaks = Vec::new();
    for line in lines {
        if let Some(caps) = closes_re().captures(line) {
            closes.push(caps.get(2).map(|m| m.as_str()).unwrap_or("").to_owned());
        }
        if let Some(caps) = breaks_re().captures(line) {
            breaks.push(caps.get(2).map(|m| m.as_str()).unwrap_or("").to_owned());
        } else if breaking_re().is_match(line) {
            breaks.push(String::new());
        }
    }

    Some((
        section,
        Commit {
            hash,
            subject,
            component,
            closes,
            breaks,
        },
    ))
}

impl SectionMap {
    /// Builds the section map from the raw output of `git log`.
    pub fn from_log(sections: &Sections, log: &str) -> SectionMap {
        let mut map: Vec<(String, BTreeMap<String, Vec<Commit>>)> = sections
            .iter()
            .map(|(title, _)| (title.clone(), BTreeMap::new()))
            .collect();
        for raw in log.split("\n==END==\n") {
            if let Some((title, commit)) = parse_raw_commit(sections, raw) {
                if let Some((_, components)) = map.iter_mut().find(|(t, _)| t == title) {
                    components
                        .entry(commit.component.clone())
                        .or_default()
                        .push(commit);
                }
            }
        }
        SectionMap {
            sections: map.into_iter().filter(|(_, c)| !c.is_empty()).collect(),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sections() -> Sections {
        vec![("Features".to_owned(), vec!["feat".to_owned()])]
    }

    #[test]
    fn parses_subject() {
        let (title, c) = parse_raw_commit(&sections(), "abc\nfeat(x): y\nCloses #1, #2\nBreaks #3\nBREAKING\n").unwrap();
        assert_eq!(title, "Features");
        assert_eq!(c.hash, "abc");
        assert_eq!(c.component, "x");
        assert_eq!(c.subject, " y");
        assert_eq!(c.closes, vec!["2"]);
        assert_eq!(c.breaks, vec!["3", ""]);
    }

    #[test]
    fn drops_unknown_types() {
        assert!(parse_raw_commit(&sections(), "abc\nfix(x): y\n").is_none());
        assert!(parse_raw_commit(&sections(), "abc\nnot conventional\n").is_none());
        assert!(parse_raw_commit(&sections(), "").is_none());
    }
}
EOF
