                LinkStyle::Github | LinkStyle::Gitlab => format!("{repo}/commit/{hash}"),
                LinkStyle::Stash => format!("{repo}/commits/{hash}"),
                LinkStyle::Cgit => format!("{repo}/commit/?id={hash}"),
            },
            None => panic::with_location(panic::LINK_SHORT_HASH, || hash[0..8].to_owned()),
        }
    }

    /// Link to an issue; falls back to the issue number itself.
    fn issue_link(self, issue: &str, repo: Option<&str>) -> String {
        match (repo, self) {
            (Some(repo), LinkStyle::Github | LinkStyle::Gitlab) => format!("{repo}/issues/{issue}"),
            _ => issue.to_owned(),
        }
    }
}

fn short_hash(hash: &str) -> &str {
    panic::with_location(panic::MD_SHORT_HASH, || &hash[0..8])
}

/// Renders `, closes [#1](link), [#2](link)` / `, breaks ...` suffixes.
fn issue_refs(ctx: &Context<'_>, label: &str, issues: &[String]) -> String {
    let links: Vec<String> = issues
        .iter()
        .map(|issue| {
            let link = ctx.link_style.issue_link(issue, ctx.repository);
            format!("[#{issue}]({link})")
        })
        .collect();
    // A lone reference without any issue information is not worth printing.
    if links.is_empty() || links == ["[#]()"] {
        return String::new();
    }
    format!(", {label} {}", links.join(", "))
}

fn commit_refs(ctx: &Context<'_>, commit: &Commit) -> String {
    let link = ctx.link_style.commit_link(&commit.hash, ctx.repository);
    format!(
        "([{}]({}){}{})",
        short_hash(&commit.hash),
        link,
        issue_refs(ctx, "closes", &commit.closes),
        issue_refs(ctx, "breaks", &commit.breaks)
    )
}

pub fn write_markdown(out: &mut dyn Write, ctx: &Context<'_>, sm: &SectionMap) -> io::Result<()> {
    let version = ctx.version.unwrap_or("");
    let subtitle = ctx.subtitle.unwrap_or("");
    let level = if ctx.patch_version { "###" } else { "##" };
    write!(
        out,
        "<a name=\"{version}\"></a>\n{level} {version} {subtitle} ({})\n\n",
        ctx.date
    )?;

    for (title, components) in &sm.sections {
        write!(out, "\n#### {title}\n\n")?;
        for (component, commits) in components {
            if component.is_empty() || commits.len() == 1 {
                for commit in commits {
                    let heading = if component.is_empty() {
                        String::new()
                    } else {
                        format!("**{component}:**")
                    };
                    write!(out, "* {heading}")?;
                    write!(out, " {} {}\n", commit.subject, commit_refs(ctx, commit))?;
                }
            } else {
                write!(out, "* **{component}:**")?;
                for commit in commits {
                    write!(out, "\n  * {} {}", commit.subject, commit_refs(ctx, commit))?;
                }
                write!(out, "\n")?;
            }
        }
    }
