    let items: Vec<String> = issues
        .iter()
        .map(|issue| {
            let link = ctx.link_style.issue_link(issue, ctx.repository);
            format!("{{\"issue\":{issue},\"issue_link\":{link:?}}}")
        })
        .collect();
    format!("[{}]", items.join(","))
}

pub fn write_json(out: &mut dyn Write, ctx: &Context<'_>, sm: &SectionMap) -> io::Result<()> {
    write!(
        out,
        "{{\"header\":{{\"version\":{:?},\"patch_version\":{},\"subtitle\":{},\"date\":{:?}}},\"sections\":",
        ctx.version,
        ctx.patch_version,
        ctx.subtitle.unwrap_or("null"),
        ctx.date
    )?;
    if sm.sections.is_empty() {
        write!(out, "null")?;
    } else {
        write!(out, "[")?;
        for (i, (title, components)) in sm.sections.iter().enumerate() {
            if i > 0 {
                write!(out, ",")?;
            }
            write!(out, "{{\"title\":{title:?},\"commits\":[")?;
            let mut first = true;
            for (component, commits) in components {
                for commit in commits {
                    if !first {
                        write!(out, ",")?;
                    }
                    first = false;
                    if component.is_empty() {
                        write!(out, "{{\"component\":null,")?;
                    } else {
                        write!(out, "{{\"component\":{component:?},")?;
                    }
                    let link = ctx.link_style.commit_link(&commit.hash, ctx.repository);
                    write!(out, "\"subject\":{:?},\"commit_link\":{:?},", commit.subject, link)?;
                    if commit.closes.is_empty() {
                        write!(out, "\"closes\":null,")?;
                    } else {
                        write!(out, "\"closes\":{},", json_issues(ctx, &commit.closes))?;
                    }
                    // Breaking changes are rendered from the closed issues.
                    if commit.breaks.is_empty() {
                        write!(out, "\"breaks\":null}}")?;
                    } else {
                        write!(out, "\"breaks\":{}}}", json_issues(ctx, &commit.closes))?;
                    }
                }
            }
            write!(out, "]}}")?;
        }
        write!(out, "]")?;
    }
    write!(out, "}}")
}
