use std::fs::{self, File};
use std::io::{self, Write};
use std::path::PathBuf;
use std::time::Instant;

use clap::ArgMatches;

use commit::{SectionMap, Sections};
use error::Error;
use git::Repo;
use version::Bump;

/// Output format of the changelog.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Format {
    Markdown,
    Json,
}

impl Format {
    pub fn parse(s: &str) -> Option<Format> {
        match s.to_lowercase().as_str() {
            "markdown" => Some(Format::Markdown),
            "json" => Some(Format::Json),
            _ => None,
        }
    }
}

/// Flavour of the generated commit/issue links.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LinkStyle {
    Github,
    Gitlab,
    Stash,
    Cgit,
}

impl LinkStyle {
    pub fn parse(s: &str) -> Option<LinkStyle> {
        match s.to_lowercase().as_str() {
            "github" => Some(LinkStyle::Github),
            "gitlab" => Some(LinkStyle::Gitlab),
            "stash" => Some(LinkStyle::Stash),
            "cgit" => Some(LinkStyle::Cgit),
            _ => None,
        }
    }
}

/// All settings gathered from the configuration file and the command line.
#[derive(Debug)]
struct Clog {
    repo: Repo,
    format: Format,
    repository: Option<String>,
    link_style: LinkStyle,
    version: Option<String>,
    patch_version: bool,
    subtitle: Option<String>,
    from: Option<String>,
    to: String,
    outfile: Option<String>,
    infile: Option<String>,
    sections: Sections,
}

impl Default for Clog {
    fn default() -> Self {
        Clog {
            repo: Repo::default(),
            format: Format::Markdown,
            repository: None,
            link_style: LinkStyle::Github,
            version: None,
            patch_version: false,
            subtitle: None,
            from: None,
            to: "HEAD".to_owned(),
            outfile: None,
            infile: None,
            sections: Vec::new(),
        }
    }
}

impl Clog {
    /// Applies the configuration file located at `path`.
    fn load_config(&mut self, path: &PathBuf) -> Result<(), Error> {
        let text = fs::read_to_string(path)?;
        let cfg = config::parse(&text)?;

        if let Some(sections) = cfg.sections {
            self.sections = sections;
        }
        if let Some(dir) = cfg.git_dir {
            self.repo.git_dir = Some(dir);
        }
        if let Some(tree) = cfg.git_work_tree {
            self.repo.work_tree = Some(tree);
        }
        if cfg.from_latest_tag == Some(true) {
            self.from = Some(self.repo.latest_tag()?);
        }
        if let Some(repository) = cfg.repository {
            self.repository = Some(repository);
        }
        if let Some(subtitle) = cfg.subtitle {
            self.subtitle = Some(subtitle);
        }
        if let Some(style) = cfg.link_style {
            self.link_style = style;
        }
        if let Some(format) = cfg.output_format {
            self.format = format;
        }
        if let Some(outfile) = cfg.outfile {
            self.outfile = Some(outfile);
        }
        if let Some(infile) = cfg.infile {
            self.infile = Some(infile);
        }
        if let Some(changelog) = cfg.changelog {
            self.outfile = Some(changelog.clone());
            self.infile = Some(changelog);
        }
        Ok(())
    }

    /// Applies the command line options; `project_dir` is the directory the
    /// configuration file lives in.
    fn apply_args(&mut self, m: &ArgMatches, project_dir: &PathBuf) -> Result<(), Error> {
        let git_dir = match m.get_one::<String>("git-dir") {
            Some(dir) => dir.clone(),
            None => project_dir.join(".git").to_string_lossy().into_owned(),
        };
        let work_tree = match m.get_one::<String>("work-tree") {
            Some(tree) => tree.clone(),
            None => project_dir.to_string_lossy().into_owned(),
        };
        self.repo.git_dir = Some(git_dir);
        self.repo.work_tree = Some(work_tree);

        self.repository = m.get_one::<String>("repository").cloned();
        self.subtitle = m.get_one::<String>("subtitle").cloned();
        self.link_style = m
            .get_one::<String>("link-style")
            .and_then(|s| LinkStyle::parse(s))
            .unwrap_or(LinkStyle::Github);
        self.format = m
            .get_one::<String>("format")
            .and_then(|s| Format::parse(s))
            .unwrap_or(Format::Markdown);

        if let Some(version) = m.get_one::<String>("setversion") {
            self.version = Some(version.clone());
        } else {
            let bump = if m.get_flag("major") {
                Some(Bump::Major)
            } else if m.get_flag("minor") {
                Some(Bump::Minor)
            } else if m.get_flag("patch") {
                self.patch_version = true;
                Some(Bump::Patch)
            } else {
                None
            };
            if let Some(bump) = bump {
                let latest = self.repo.latest_tag_name()?;
                self.version = Some(version::bump(&latest, bump)?);
            }
        }

        if m.get_flag("from-latest-tag") {
            self.from = Some(self.repo.latest_tag()?);
        }
        if let Some(from) = m.get_one::<String>("from") {
            self.from = Some(from.clone());
        }
        if let Some(to) = m.get_one::<String>("to") {
            self.to = to.clone();
        }

        if let Some(outfile) = m.get_one::<String>("outfile") {
            self.outfile = Some(outfile.clone());
        }
        if let Some(infile) = m.get_one::<String>("infile") {
            self.infile = Some(infile.clone());
        }
        if let Some(changelog) = m.get_one::<String>("changelog") {
            self.outfile = Some(changelog.clone());
            self.infile = Some(changelog.clone());
        }
        Ok(())
    }

    /// Generates the changelog and writes it to the configured destination.
    fn write_changelog(&self) -> Result<(), Error> {
        // Previous changelog contents are prepended-to; reading failures
        // simply mean there is nothing to keep.
        let previous = self
            .infile
            .as_ref()
            .or(self.outfile.as_ref())
            .map(|path| fs::read_to_string(path).unwrap_or_default());

        let mut out: Box<dyn Write> = match &self.outfile {
            Some(path) => Box::new(File::create(path)?),
            None => Box::new(io::stdout()),
        };

        let range = match &self.from {
            Some(from) => format!("{}..{}", from, self.to),
            None => "HEAD".to_owned(),
        };
        let log = self.repo.log(&range)?;
        let sections = SectionMap::from_log(&self.sections, &log);

        let date = date::today_utc();
        let ctx = writer::Context {
            version: self.version.as_deref(),
            patch_version: self.patch_version,
            subtitle: self.subtitle.as_deref(),
            date: &date,
            repository: self.repository.as_deref(),
            link_style: self.link_style,
        };
        match self.format {
            Format::Markdown => writer::write_markdown(&mut *out, &ctx, &sections)?,
            Format::Json => writer::write_json(&mut *out, &ctx, &sections)?,
        }
        if let Some(previous) = previous {
            out.write_all(b"\n\n\n")?;
            out.write_all(previous.as_bytes())?;
        }
        out.flush()?;
        Ok(())
    }
}

fn run() -> Result<(), Error> {
    let matches = cli::build().get_matches();

    let cwd = std::env::current_dir()?;
    let config_path = cwd.join(matches.get_one::<String>("config").map(String::as_str).unwrap_or(".clog.toml"));
    let project_dir = config_path
        .parent()
        .map(PathBuf::from)
        .unwrap_or_else(|| config_path.clone());

    let mut clog = Clog::default();
    clog.load_config(&config_path)?;
    clog.apply_args(&matches, &project_dir)?;
    clog.write_changelog()
}

fn main() {
    let start = Instant::now();
    panic::install();
    match run() {
        Ok(()) => {
            println!("changelog written. (took {} ms)", start.elapsed().as_millis());
        }
        Err(e) => {
            eprintln!("\x1b[1;31merror:\x1b[0m {e}");
            std::process::exit(1);
        }
    }
}
