//! Invocation of the `git` command line tool.

use std::process::Command;

use crate::error::Error;
use crate::panic;

/// Default sections and their aliases; only used to build the `--grep`
/// filter passed to `git log`.
const DEFAULT_SECTIONS: [(&str, &[&str]); 5] = [
    ("Features", &["ft", "feat"]),
    ("Bug Fixes", &["fx", "fix"]),
    ("Performance", &["perf"]),
    ("Unknown", &["unk"]),
    ("Breaking Changes", &["breaks"]),
];

/// Builds the extended regular expression handed to `git log --grep`.
pub fn grep_pattern() -> String {
    let mut grep = String::new();
    for (_, aliases) in DEFAULT_SECTIONS {
        grep.push('^');
        for alias in aliases {
            grep.push('^');
            grep.push_str(alias);
            grep.push('|');
        }
        grep.push('|');
    }
    grep.push_str("BREAKING'");
    grep
}

/// Location of the repository as passed to git.
#[derive(Debug, Clone, Default)]
pub struct Repo {
    pub git_dir: Option<String>,
    pub work_tree: Option<String>,
}

impl Repo {
    /// The `--git-dir`/`--work-tree` arguments.  Both are empty when nothing
    /// is configured; configuring only one of them is not supported.
    fn dir_args(&self) -> (String, String) {
        match (&self.git_dir, &self.work_tree) {
            (Some(dir), Some(tree)) => (format!("--git-dir={dir}"), format!("--work-tree={tree}")),
            (Some(_), None) => panic::unwrap_none(panic::GIT_DIR_ONLY),
            (None, Some(_)) => panic::unwrap_none(panic::WORK_TREE_ONLY),
            (None, None) => (String::new(), String::new()),
        }
    }

    /// Runs `git <args>` and returns its standard output (lossily decoded).
    /// A failing git command simply yields its (possibly empty) output.
    fn run(&self, args: &[&str]) -> Result<String, Error> {
        let (dir, tree) = self.dir_args();
        let output = Command::new("git").arg(dir).arg(tree).args(args).output()?;
        Ok(String::from_utf8_lossy(&output.stdout).into_owned())
    }

    /// Hash of the most recent tag (empty when there is none).
    pub fn latest_tag(&self) -> Result<String, Error> {
        Ok(self.run(&["rev-list", "--tags", "--max-count=1"])?.trim().to_owned())
    }

    /// Raw output of `git describe --tags --abbrev=0`.
    pub fn latest_tag_name(&self) -> Result<String, Error> {
        self.run(&["describe", "--tags", "--abbrev=0"])
    }

    /// Raw commit log for `range`, one `%H%n%s%n%b%n==END==` block per commit.
    pub fn log(&self, range: &str) -> Result<String, Error> {
        let grep = format!("--grep={}", grep_pattern());
        self.run(&["log", "-E", &grep, "--format=%H%n%s%n%b%n==END==", range])
    }
}

#[cfg(test)]
mod tests {
    #[test]
    fn grep() {
        assert_eq!(
            super::grep_pattern(),
            "^^ft|^feat||^^fx|^fix||^^perf||^^unk||^^breaks||BREAKING'"
        );
    }
}
