//! Minimal terminal size query with the same API surface as the
//! `terminal_size` crate, implemented locally with `ioctl(TIOCGWINSZ)`.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Width(pub u16);
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Height(pub u16);

/// Size of the terminal attached to stdout, falling back to stderr and then
/// stdin.
pub fn terminal_size() -> Option<(Width, Height)> {
    [libc::STDOUT_FILENO, libc::STDERR_FILENO, libc::STDIN_FILENO]
        .into_iter()
        .find_map(terminal_size_of_fd)
}

/// Size of the terminal attached to the file descriptor `fd`, if any.
pub fn terminal_size_of_fd(fd: libc::c_int) -> Option<(Width, Height)> {
    // SAFETY: `ws` is a plain C struct that the ioctl fills in; `fd` is only
    // inspected, never closed.
    unsafe {
        if libc::isatty(fd) != 1 {
            return None;
        }
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) == -1 {
            return None;
        }
        if ws.ws_col == 0 || ws.ws_row == 0 {
            return None;
        }
        Some((Width(ws.ws_col), Height(ws.ws_row)))
    }
}
